1	package nexusbench
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"net/url"
11		"slices"
12		"strings"
13		"time"
14	)
15	
16	const (
17		// clientTimeout bounds every REST call, connection included.
18		clientTimeout = 15 * time.Second
19		// maxResponseBytes is the most the client reads from one answer. A larger
20		// one is an error, and its content is never decoded.
21		maxResponseBytes = 1 << 20
22		// drainBytes is how much of an unwanted answer is read so the connection
23		// can be reused.
24		drainBytes = 4 << 10
25	)
26	
27	// APIError is a REST call the instance answered with a status outside 2xx. It
28	// carries the operation and the status only: no URL, no request body, no answer
29	// body, because any of them could hold a credential.
30	type APIError struct {
31		// Op says what the call was for, e.g. "create user bench-pull".
32		Op     string
33		Status int
34		// RemoteURLBlocked is true for a 400 whose validation errors name
35		// proxy.remoteUrl: Nexus 3.98.1 resolves the host of a proxy's remote URL
36		// when it saves the repository and refuses one that does not resolve. Only
37		// this verdict is kept, never the text of the answer.
38		RemoteURLBlocked bool
39	}
40	
41	// Error returns "<Op>: HTTP <status> <text>".
42	func (e *APIError) Error() string {
43		return strings.TrimSpace(fmt.Sprintf("%s: HTTP %d %s", e.Op, e.Status, http.StatusText(e.Status)))
44	}
45	
46	// transportError is a call that got no answer: connection refused, reset,
47	// timeout. The cause stays in Err; its text carries the URL and is not printed.
48	type transportError struct {
49		Op  string
50		Err error
51	}
52	
53	func (e *transportError) Error() string { return "no answer to " + e.Op }
54	func (e *transportError) Unwrap() error { return e.Err }
55	
56	// tooLargeError is an answer past maxResponseBytes.
57	type tooLargeError struct{ Op string }
58	
59	func (e *tooLargeError) Error() string {
60		return fmt.Sprintf("the answer to %s is larger than %d bytes", e.Op, maxResponseBytes)
61	}
62	
63	// decodeError is an answer that is not the JSON the client expects.
64	type decodeError struct {
65		Op  string
66		Err error
67	}
68	
69	func (e *decodeError) Error() string { return "unexpected answer to " + e.Op }
70	func (e *decodeError) Unwrap() error { return e.Err }
71	
72	// client is the REST client of one Nexus instance. It follows no redirection
73	// (an answer that moves the call elsewhere would carry the credentials with
74	// it), reads at most maxResponseBytes of an answer, and never logs a header.
75	type client struct {
76		base     string
77		user     string
78		REDACTED string
79		http     *http.Client
80	}
81	
82	// newClient returns a client for baseURL, authenticating with Basic auth as user
83	// unless user is empty (the calls that need no account).
84	func newClient(baseURL, user, REDACTED string) *client {
85		transport := http.DefaultTransport.(*http.Transport).Clone()
86		// The bench is reached directly: a proxy named by the environment would
87		// receive the credentials.
88		transport.Proxy = nil
89		return &client{
90			base:     strings.TrimRight(baseURL, "/"),
91			user:     user,
92			REDACTED: REDACTED,
93			http: &http.Client{
94				Timeout:       clientTimeout,
95				Transport:     transport,
96				CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
97			},
98		}
99	}
100	
101	// closeIdle drops the connections the client keeps open.
102	func (c *client) closeIdle() { c.http.CloseIdleConnections() }
103	
104	// request is one REST call.
105	type request struct {
106		op          string
107		method      string
108		path        string
109		query       url.Values
110		contentType string
111		body        []byte
112	}
113	
114	// response is what the instance answered.
115	type response struct {
116		status int
117		header http.Header
118		body   []byte
119		// remoteURLBlocked is the verdict of remoteURLRefused on a 400; the body of
120		// an answer outside 2xx is read for it and dropped.
121		remoteURLBlocked bool
122	}
123	
124	// do sends r and returns the answer whatever its status. The error is a
125	// *transportError or a *tooLargeError.
126	func (c *client) do(ctx context.Context, r request) (response, error) {
127		target := c.base + r.path
128		if len(r.query) > 0 {
129			target += "?" + r.query.Encode()
130		}
131		var body io.Reader
132		if r.body != nil {
133			body = bytes.NewReader(r.body)
134		}
135		req, err := http.NewRequestWithContext(ctx, r.method, target, body)
136		if err != nil {
137			return response{}, &transportError{Op: r.op, Err: err}
138		}
139		req.Header.Set("Accept", "application/json")
140		if r.contentType != "" {
141			req.Header.Set("Content-Type", r.contentType)
142		}
143		if c.user != "" {
144			req.SetBasicAuth(c.user, c.REDACTED)
145		}
146		resp, err := c.http.Do(req)
147		if err != nil {
148			return response{}, &transportError{Op: r.op, Err: err}
149		}
150		defer func() { _ = resp.Body.Close() }()
151		if resp.StatusCode < 200 || resp.StatusCode > 299 {
152			refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
153			return response{
154				status: resp.StatusCode, header: resp.Header,
155				remoteURLBlocked: resp.StatusCode == http.StatusBadRequest && remoteURLRefused(refused),
156			}, nil
157		}
158		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
159		if err != nil {
160			return response{}, &transportError{Op: r.op, Err: err}
161		}
162		if len(data) > maxResponseBytes {
163			return response{}, &tooLargeError{Op: r.op}
164		}
165		return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
166	}
167	
168	// expect sends r and turns a status outside 2xx into an *APIError.
169	func (c *client) expect(ctx context.Context, r request) (response, error) {
170		resp, err := c.do(ctx, r)
171		if err != nil {
172			return resp, err
173		}
174		if resp.status < 200 || resp.status > 299 {
175			return resp, &APIError{Op: r.op, Status: resp.status, RemoteURLBlocked: resp.remoteURLBlocked}
176		}
177		return resp, nil
178	}
179	
180	// remoteURLRefused reports whether body is a Nexus validation error list with
181	// an entry on proxy.remoteUrl whose message says the host did not resolve:
182	// [{"id":"HelperBean.proxy.remoteUrl","message":"... Failed to resolve host: ..."}].
183	// Only that verdict leaves the function: no text of the answer is kept. The
184	// content type of the answer is vendor specific, so only the JSON is read; a
185	// body past drainBytes was cut and is not trusted.
186	func remoteURLRefused(body []byte) bool {
187		if len(body) > drainBytes {
188			return false
189		}
190		var errs []validationError
191		if err := json.Unmarshal(body, &errs); err != nil {
192			return false
193		}
194		return slices.ContainsFunc(errs, func(e validationError) bool {
195			return strings.HasSuffix(e.ID, "proxy.remoteUrl") &&
196				strings.Contains(strings.ToLower(e.Message), "resolve host")
197		})
198	}
199	
200	// validationError is one entry of a Nexus validation error list. The message is
201	// only matched by remoteURLRefused, never stored or shown.
202	type validationError struct {
203		ID      string `json:"id"`
204		Message string `json:"message"`
205	}
206	
207	// get reads path and decodes the JSON answer into out (nil: not decoded). A 404
208	// is found == false without an error.
209	func (c *client) get(ctx context.Context, op, path string, query url.Values, out any) (found bool, err error) {
210		resp, err := c.do(ctx, request{op: op, method: http.MethodGet, path: path, query: query})
211		if err != nil {
212			return false, err
213		}
214		switch {
215		case resp.status == http.StatusNotFound:
216			return false, nil
217		case resp.status < 200 || resp.status > 299:
218			return false, &APIError{Op: op, Status: resp.status}
219		}
220		if out == nil {
221			return true, nil
222		}
223		if err := json.Unmarshal(resp.body, out); err != nil {
224			return false, &decodeError{Op: op, Err: err}
225		}
226		return true, nil
227	}
228	
229	// read is get for an object that has to exist: a 404 is an *APIError.
230	func (c *client) read(ctx context.Context, op, path string, query url.Values, out any) error {
231		found, err := c.get(ctx, op, path, query, out)
232		if err != nil {
233			return err
234		}
235		if !found {
236			return &APIError{Op: op, Status: http.StatusNotFound}
237		}
238		return nil
239	}
240	
241	// write sends payload as JSON with method and expects a 2xx.
242	func (c *client) write(ctx context.Context, op, method, path string, payload any) error {
243		data, err := json.Marshal(payload)
244		if err != nil {
245			return &decodeError{Op: op, Err: err}
246		}
247		_, err = c.expect(ctx, request{op: op, method: method, path: path, contentType: "application/json", body: data})
248		return err
249	}
250

1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"log/slog"
11		"os"
12		"os/exec"
13		"path/filepath"
14		"runtime"
15		"strings"
16		"time"
17	)
18	
19	const (
20		// secretsFileName is the only file name a store accepts: Remove deletes the
21		// file, and a mistyped NEXUS_BENCH_SECRETS must not point it at a key file.
22		secretsFileName = "secrets.json"
23		secretsFileMode = 0o600
24		secretsDirMode  = 0o700
25		// gitCheckTimeout bounds the one git process the store may start.
26		gitCheckTimeout = 10 * time.Second
27		// redactedSecrets is what a Secrets shows in place of its values.
28		redactedSecrets = "Secrets{redacted}"
29	)
30	
31	// Secrets are the passwords of the bench. They live in the secrets file and
32	// nowhere else: not in the descriptor, not in a manifest, not in an error.
33	type Secrets struct {
34		// AdminPassword is the current password of the admin account.
35		AdminPassword string `json:"adminPassword"`
36		// PendingAdminPassword is the new admin password, written before it is sent
37		// to Nexus so that an interrupted change does not lose it.
38		PendingAdminPassword string `json:"pendingAdminPassword,omitempty"`
39		// PullPassword is the password of the read-only bench-pull account.
40		PullPassword string `json:"pullPassword,omitempty"`
41	}
42	
43	// String implements fmt.Stringer so that %v, %+v and %s never print a password.
44	func (Secrets) String() string { return redactedSecrets }
45	
46	// GoString implements fmt.GoStringer so that %#v never prints a password.
47	func (Secrets) GoString() string { return redactedSecrets }
48	
49	// LogValue implements slog.LogValuer so that a logger never records a password.
50	func (Secrets) LogValue() slog.Value { return slog.StringValue(redactedSecrets) }
51	
52	// SecretStore keeps the Secrets of one bench (one context and namespace).
53	type SecretStore interface {
54		// Load returns the stored secrets; found is false, without an error, when
55		// nothing is stored yet.
56		Load() (s Secrets, found bool, err error)
57		// Save replaces the stored secrets atomically.
58		Save(Secrets) error
59		// Remove deletes the stored secrets. It succeeds when there are none.
60		Remove() error
61	}
62	
63	// DefaultSecretsPath returns where the secrets of a bench live:
64	// <state>/devdesk/nexus-bench/<context>/<namespace>/secrets.json, with <state>
65	// the XDG_STATE_HOME variable, else ~/.local/state. The folder is outside every
66	// repository and shared by all the worktrees of the project. getenv is os.Getenv
67	// in production; an empty variable counts as unset.
68	func DefaultSecretsPath(kubeContext, namespace string, getenv func(string) string) (string, error) {
69		for _, part := range []string{kubeContext, namespace} {
70			if part == "" || part == "." || part == ".." || strings.ContainsAny(part, `/\`) {
71				return "", fmt.Errorf("%q cannot name a folder of the secrets path", part)
72			}
73		}
74		state := getenv("XDG_STATE_HOME")
75		if state == "" {
76			home := getenv("HOME")
77			if home == "" {
78				home = getenv("USERPROFILE")
79			}
80			if home == "" {
81				return "", errors.New("cannot place the secrets file: neither XDG_STATE_HOME nor HOME is set; set NEXUS_BENCH_SECRETS to a path outside the repository")
82			}
83			state = filepath.Join(home, ".local", "state")
84		}
85		return filepath.Join(state, "devdesk", "nexus-bench", kubeContext, namespace, secretsFileName), nil
86	}
87	
88	// fileStore is the SecretStore backed by one JSON file.
89	type fileStore struct{ path string }
90	
91	// NewFileStore returns the store of the file at path. It touches nothing on
92	// disk. A path inside a git working tree is refused unless git ignores it, so
93	// that a secret cannot be committed by accident; a path outside every
94	// repository is accepted without asking git. The file must be named
95	// secrets.json: the store deletes it on Remove.
96	func NewFileStore(path string) (SecretStore, error) {
97		if path == "" {
98			return nil, errors.New("the secrets path is empty")
99		}
100		abs, err := filepath.Abs(path)
101		if err != nil {
102			return nil, fmt.Errorf("resolve the secrets path: %w", err)
103		}
104		if filepath.Base(abs) != secretsFileName {
105			return nil, &BenchError{
106				Cause: fmt.Sprintf("the secrets path %s does not name a file called %s, and the bench deletes that file on down", abs, secretsFileName),
107				Check: "set NEXUS_BENCH_SECRETS to <folder>/" + secretsFileName + ", in a folder of its own",
108			}
109		}
110		if root, inRepo := findGitRoot(filepath.Dir(abs)); inRepo {
111			ignored, err := gitIgnores(root, abs)
112			if err != nil {
113				return nil, &BenchError{
114					Cause: fmt.Sprintf("the secrets path %s is inside the git repository %s and git could not tell whether it is ignored", abs, root),
115					Check: "run git check-ignore -v on that path, or set NEXUS_BENCH_SECRETS to a path outside the repository",
116					Err:   err,
117				}
118			}
119			if !ignored {
120				return nil, &BenchError{
121					Cause: fmt.Sprintf("the secrets path %s is inside the git repository %s and is not ignored by git, so the passwords could be committed", abs, root),
122					Check: "set NEXUS_BENCH_SECRETS to a path outside the repository, or add the file to .gitignore",
123				}
124			}
125		}
126		return &fileStore{path: abs}, nil
127	}
128	
129	// findGitRoot walks up from dir (which may not exist yet) to the first folder
130	// that holds a .git entry, a directory or a file as in a worktree.
131	func findGitRoot(dir string) (root string, ok bool) {
132		for {
133			if _, err := os.Lstat(filepath.Join(dir, ".git")); err == nil {
134				return dir, true
135			}
136			parent := filepath.Dir(dir)
137			if parent == dir {
138				return "", false
139			}
140			dir = parent
141		}
142	}
143	
144	// gitIgnores reports whether git ignores path inside the working tree at root.
145	// It is a variable so a test can replace the one process the package starts for
146	// the guard; kubectl.go stays the only file that starts one otherwise.
147	var gitIgnores = func(root, path string) (bool, error) {
148		ctx, cancel := context.WithTimeout(context.Background(), gitCheckTimeout)
149		defer cancel()
150		cmd := exec.CommandContext(ctx, "git", "-C", root, "check-ignore", "-q", "--", path) //nolint:gosec // fixed arguments, the paths come from the caller's own configuration
151		cmd.Env = gitEnvironment()
152		err := cmd.Run()
153		if err == nil {
154			return true, nil // exit 0: the path is ignored
155		}
156		var exit *exec.ExitError
157		if errors.As(err, &exit) && exit.ExitCode() == 1 {
158			return false, nil // exit 1: the path is not ignored
159		}
160		return false, err // git missing, exit 128 (not a repository, bad path), timeout
161	}
162	
163	// gitEnvironment is the environment of the git process: the caller's, without
164	// the variables that point git at a repository or inject a configuration.
165	// Inherited, GIT_DIR and its siblings would make git judge another repository
166	// than the one holding the path; GIT_CONFIG_COUNT/KEY/VALUE and
167	// GIT_CONFIG_PARAMETERS could add a core.excludesFile that ignores the secrets
168	// file; GIT_CEILING_DIRECTORIES could hide the repository. The user and system
169	// configuration are switched off, so only the rules of the repository itself
170	// (.gitignore, .git/info/exclude) can say a path is ignored. Names are compared
171	// in upper case because Windows environment names are case-insensitive.
172	func gitEnvironment() []string {
173		var env []string
174		for _, kv := range os.Environ() {
175			name, _, _ := strings.Cut(kv, "=")
176			upper := strings.ToUpper(name)
177			switch upper {
178			case "GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_COMMON_DIR", "GIT_OBJECT_DIRECTORY", "GIT_NAMESPACE",
179				"GIT_CONFIG_PARAMETERS", "GIT_CONFIG_COUNT", "GIT_CONFIG_GLOBAL", "GIT_CONFIG_SYSTEM", "GIT_CONFIG_NOSYSTEM",
180				"GIT_CEILING_DIRECTORIES":
181				continue
182			}
183			if strings.HasPrefix(upper, "GIT_CONFIG_KEY_") || strings.HasPrefix(upper, "GIT_CONFIG_VALUE_") {
184				continue
185			}
186			env = append(env, kv)
187		}
188		return append(env, "GIT_CONFIG_GLOBAL="+os.DevNull, "GIT_CONFIG_NOSYSTEM=1")
189	}
190	
191	// Load implements SecretStore. The error never carries the content of the
192	// file: a corrupt file may hold a password.
193	func (s *fileStore) Load() (Secrets, bool, error) {
194		f, err := os.Open(s.path)
195		if errors.Is(err, fs.ErrNotExist) {
196			return Secrets{}, false, nil
197		}
198		if err != nil {
199			return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
200		}
201		defer func() { _ = f.Close() }()
202		info, err := f.Stat()
203		if err != nil {
204			return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
205		}
206		// Windows has no group or other bits to read.
207		if runtime.GOOS != "windows" && info.Mode().Perm()&0o077 != 0 {
208			return Secrets{}, false, &BenchError{
209				Cause: fmt.Sprintf("the secrets file %s can be read by other accounts (mode %04o)", s.path, info.Mode().Perm()),
210				Check: "chmod 600 " + s.path,
211			}
212		}
213		data, err := io.ReadAll(f)
214		if err != nil {
215			return Secrets{}, false, fmt.Errorf("read the secrets file: %w", err)
216		}
217		var out Secrets
218		if err := json.Unmarshal(data, &out); err != nil {
219			return Secrets{}, false, &BenchError{
220				Cause: fmt.Sprintf("the secrets file %s is not valid", s.path),
221				Check: "delete the file and run the bench again, or restore it from a copy; its content is not shown",
222				Err:   err,
223			}
224		}
225		return out, true, nil
226	}
227	
228	// Save implements SecretStore.
229	func (s *fileStore) Save(secrets Secrets) error {
230		data, err := json.MarshalIndent(secrets, "", "  ")
231		if err != nil {
232			return fmt.Errorf("encode the secrets: %w", err)
233		}
234		return writeFileAtomic(s.path, append(data, '\n'), secretsFileMode, secretsDirMode)
235	}
236	
237	// Remove implements SecretStore. It deletes the file, then its folder when
238	// that is empty; a folder that holds anything else stays.
239	func (s *fileStore) Remove() error {
240		if err := os.Remove(s.path); err != nil && !errors.Is(err, fs.ErrNotExist) {
241			return fmt.Errorf("remove the secrets file: %w", err)
242		}
243		dir := filepath.Dir(s.path)
244		entries, err := os.ReadDir(dir)
245		if errors.Is(err, fs.ErrNotExist) || (err == nil && len(entries) > 0) {
246			return nil
247		}
248		if err != nil {
249			return fmt.Errorf("read the secrets folder: %w", err)
250		}
251		if err := os.Remove(dir); err != nil && !errors.Is(err, fs.ErrNotExist) {
252			return fmt.Errorf("remove the secrets folder: %w", err)
253		}
254		return nil
255	}
256	
257	// writeFileAtomic writes data to path through a temporary file of the same
258	// folder and a rename, so a reader sees the old file or the new one, never a
259	// partial one. Missing folders are created with dirMode. The temporary file is
260	// removed when anything fails. The error text holds paths, never data.
261	func writeFileAtomic(path string, data []byte, fileMode, dirMode os.FileMode) (err error) {
262		dir := filepath.Dir(path)
263		if err := os.MkdirAll(dir, dirMode); err != nil {
264			return fmt.Errorf("create the folder %s: %w", dir, err)
265		}
266		tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".*.tmp")
267		if err != nil {
268			return fmt.Errorf("create a temporary file in %s: %w", dir, err)
269		}
270		defer func() {
271			if err != nil {
272				_ = tmp.Close()
273				_ = os.Remove(tmp.Name())
274			}
275		}()
276		if _, err = tmp.Write(data); err != nil {
277			return fmt.Errorf("write %s: %w", tmp.Name(), err)
278		}
279		if err = tmp.Chmod(fileMode); err != nil {
280			return fmt.Errorf("set the mode of %s: %w", tmp.Name(), err)
281		}
282		if err = tmp.Sync(); err != nil {
283			return fmt.Errorf("sync %s: %w", tmp.Name(), err)
284		}
285		if err = tmp.Close(); err != nil {
286			return fmt.Errorf("close %s: %w", tmp.Name(), err)
287		}
288		if err = os.Rename(tmp.Name(), path); err != nil {
289			return fmt.Errorf("replace %s: %w", path, err)
290		}
291		syncDir(dir)
292		return nil
293	}
294	
295	// syncDir flushes the folder entry written by the rename. Syncing the file
296	// alone does not make the new name durable: after a power cut the folder could
297	// still list the old file, and a password written just before it was sent to
298	// Nexus would be lost. It is best effort: Windows cannot open a folder for
299	// syncing and some file systems do not support it, and the file is already
300	// replaced either way, so every error is ignored.
301	func syncDir(dir string) {
302		d, err := os.Open(dir)
303		if err != nil {
304			return
305		}
306		_ = d.Sync()
307		_ = d.Close()
308	}
309

