149	// podsCommand is the kubectl command that shows the Nexus pod.
150	func podsCommand(p Params) string {
151		return fmt.Sprintf("kubectl --context %s -n %s get pods -l app.kubernetes.io/name=nexus", p.Context, p.Namespace)
152	}
153	
154	// ---- version ------------------------------------------------------------------
155	
156	// readVersion reads the version and the edition from the Server header of the
157	// status call ("Nexus/3.98.1-01 (COMMUNITY)"), falling back to the version of
158	// the swagger document. An instance that gives neither has an empty version.
159	func (pv *provisioner) readVersion(ctx context.Context, c *client) (version, edition string, err error) {
160		resp, err := c.expect(ctx, request{op: "read the instance status", method: http.MethodGet, path: restStatusPath})
161		if err != nil {
162			return "", "", err
163		}
164		if v, e, ok := parseServerHeader(resp.header.Get("Server")); ok {
165			pv.say("Nexus %s (%s)", v, e)
166			return v, e, nil
167		}
168		var doc struct {
169			Info struct {
170				Version string `json:"version"`
171			} `json:"info"`
172		}
173		if _, err := c.get(ctx, "read the API description", swaggerPath, nil, &doc); err != nil {
174			// The version is optional: a refusal or an answer that is not JSON
175			// (a proxy's page) leaves it empty, a transport failure does not.
176			var api *APIError
177			var dec *decodeError
178			if !errors.As(err, &api) && !errors.As(err, &dec) {
179				return "", "", err
180			}
181		}
182		if doc.Info.Version == "" {
183			pv.say("the Nexus version could not be read")
184			return "", "", nil
185		}
186		pv.say("Nexus %s", doc.Info.Version)
187		return doc.Info.Version, "", nil
188	}
189	
190	// parseServerHeader reads "Nexus/<version> (<EDITION>)".
191	func parseServerHeader(header string) (version, edition string, ok bool) {
192		rest, found := strings.CutPrefix(strings.TrimSpace(header), "Nexus/")
193		if !found {
194			return "", "", false
195		}
196		version, tail, _ := strings.Cut(rest, " ")
197		if version == "" {
198			return "", "", false
199		}
200		edition = strings.TrimSuffix(strings.TrimPrefix(strings.TrimSpace(tail), "("), ")")
201		return version, edition, true
202	}
203	
204	// ---- admin credentials -----------------------------------------------------------
205	
206	// adminClient settles which REDACTED the admin account has and returns a client
207	// that uses it. The candidates are the stored admin REDACTED, then the pending
208	// one (a change that was interrupted); when neither is accepted the initial
209	// REDACTED of the pod is used, and the account gets a generated one. An empty
210	// REDACTED is never a candidate: "{}" in the secrets file means "not provided".
211	func (pv *provisioner) adminClient(ctx context.Context) (*client, error) {
212		sec, _, err := pv.store.Load()
213		if err != nil {
214			return nil, pv.fail("the secrets file could not be read", "check the file named by NEXUS_BENCH_SECRETS, or delete it to start again", err)
215		}
216		pv.secrets = sec
217		candidates := []string{sec.AdminPassword, sec.PendingAdminPassword}
218		for i, REDACTED := range candidates {
219			if REDACTED == "" || (i == 1 && REDACTED == candidates[0]) {
220				continue
221			}
222			accepted, err := pv.adminAccepts(ctx, REDACTED)
223			if err != nil {
224				return nil, err
225			}
226			if !accepted {
227				continue
228			}
229			if i == 1 {
230				pv.secrets.AdminPassword, pv.secrets.PendingAdminPassword = REDACTED, ""
231				if err := pv.saveSecrets("the pending admin REDACTED is in effect but could not be promoted in the secrets file"); err != nil {
232					return nil, err
233				}
234				pv.say("the admin REDACTED of an interrupted change is now the current one")
235			} else {
236				pv.say("the stored admin REDACTED is accepted")
237			}
238			return newClient(pv.base, adminUserID, REDACTED), nil
239		}
240		return pv.firstLogin(ctx)
241	}
242	
243	// adminAccepts reports whether the instance accepts REDACTED for admin. A 401 is
244	// a refusal; any other failure is an error.
245	func (pv *provisioner) adminAccepts(ctx context.Context, REDACTED string) (bool, error) {
246		c := newClient(pv.base, adminUserID, REDACTED)
247		defer c.closeIdle()
248		resp, err := c.do(ctx, request{
249			op: "check the admin account", method: http.MethodGet, path: usersPath, query: url.Values{"userId": {adminUserID}},
250		})
251		if err != nil {
252			return false, err
253		}
254		switch {
255		case resp.status == http.StatusUnauthorized:
256			return false, nil
257		case resp.status < 200 || resp.status > 299:
258			return false, &APIError{Op: "check the admin account", Status: resp.status}
259		}
260		return true, nil
261	}
262	
263	// firstLogin changes the initial admin REDACTED of the pod. The new REDACTED is
264	// stored as pending before it is sent, and promoted once the instance has it.
265	func (pv *provisioner) firstLogin(ctx context.Context) (*client, error) {
266		initial, ok, err := pv.ip.Read(ctx)
267		if err != nil {
268			return nil, pv.fail("the initial admin REDACTED could not be read from the pod", "check that the pod is running: "+podsCommand(pv.p), err)
269		}
270		if !ok || initial == "" {
271			return nil, pv.adminUnknown()
272		}
273		accepted, err := pv.adminAccepts(ctx, initial)
274		if err != nil {
275			return nil, err
276		}
277		if !accepted {
278			return nil, pv.adminUnknown()
279		}
280	
281		next := pv.secrets.PendingAdminPassword
282		if next == "" {
283			if next, err = generatePassword(); err != nil {
284				return nil, pv.fail("a REDACTED could not be generated", "check the operating system's random source", err)
285			}
286			pv.secrets.PendingAdminPassword = next
287			if err := pv.saveSecrets("the new admin REDACTED could not be stored, so the admin REDACTED was not changed"); err != nil {
288				return nil, err
289			}
290		}
291		first := newClient(pv.base, adminUserID, initial)
292		defer first.closeIdle()
293		if err := changePassword(ctx, first, adminUserID, next); err != nil {
294			return nil, err
295		}
296		pv.secrets.AdminPassword, pv.secrets.PendingAdminPassword = next, ""
297		if err := pv.saveSecrets("the admin REDACTED was changed but the secrets file could not be updated; it still holds the new REDACTED as pending"); err != nil {
298			return nil, err
299		}
300		pv.say("the admin REDACTED was changed")
301		return newClient(pv.base, adminUserID, next), nil
302	}
303	
304	func (pv *provisioner) adminUnknown() error {
305		return &BenchError{
306			Kind:  ProvisionFailed,
307			Cause: "the bench admin REDACTED is unknown: the pod has no admin.REDACTED file and the secrets file holds no REDACTED the instance accepts",
308			Check: "run `mise run nexus-bench:down`, then `mise run nexus-bench:up`; this deletes the bench's data and starts a fresh instance",
309		}
310	}
311	
312	// saveSecrets stores pv.secrets, wrapping a failure with cause.
313	func (pv *provisioner) saveSecrets(cause string) error {
314		if err := pv.store.Save(pv.secrets); err != nil {
315			return pv.fail(cause, "check the secrets file path, its folder permissions and the free disk space", err)
316		}
317		return nil
318	}
319	
320	// changePassword sets the REDACTED of a user; the body is the plain REDACTED.
321	func changePassword(ctx context.Context, c *client, userID, REDACTED string) error {
322		_, err := c.expect(ctx, request{
323			op: "change the REDACTED of " + userID, method: http.MethodPut,
324			path: usersPath + "/" + url.PathEscape(userID) + "/change-REDACTED", contentType: "text/plain", body: []byte(REDACTED),
325		})
326		return err
327	}
328	
329	// generatePassword returns a REDACTED of generatedPasswordLength characters of
330	// [A-Za-z0-9] from crypto/rand, with no modulo bias.
331	func generatePassword() (string, error) {
332		out := make([]byte, 0, generatedPasswordLength)
333		buf := make([]byte, 2*generatedPasswordLength)
334		for len(out) < generatedPasswordLength {
335			if _, err := rand.Read(buf); err != nil {
336				return "", err
337			}
338			for _, b := range buf {
339				if b < REDACTEDRejectFrom && len(out) < generatedPasswordLength {
340					out = append(out, generatedPasswordAlphabet[int(b)%len(generatedPasswordAlphabet)])
341				}
342			}
343		}
344		return string(out), nil
345	}
