347	// ---- EULA --------------------------------------------------------------------------
348	
349	// ensureEULA reports whether the EULA is accepted at the end. It accepts it only
350	// when the operator allowed it, sending the disclaimer exactly as the instance
351	// served it; otherwise it stops, before anything is created.
352	func (pv *provisioner) ensureEULA(ctx context.Context) (bool, error) {
353		var eula struct {
354			Accepted   bool            `json:"accepted"`
355			Disclaimer json.RawMessage `json:"disclaimer"`
356		}
357		found, err := pv.api.get(ctx, "read the EULA", eulaPath, nil, &eula)
358		if err != nil {
359			return false, err
360		}
361		if !found {
362			pv.say("this instance has no EULA endpoint")
363			return false, nil
364		}
365		if eula.Accepted {
366			pv.say("the EULA is already accepted")
367			return true, nil
368		}
369		if !pv.p.AcceptEULA {
370			return false, &BenchError{
371				Kind:  ProvisionFailed,
372				Cause: "the Nexus EULA is not accepted and " + envAcceptEULA + " is not set to yes, so no repository, role or account was created",
373				Check: "read the EULA in the Nexus UI, then run again with " + envAcceptEULA + "=yes if you accept it",
374			}
375		}
376		payload := struct {
377			Accepted   bool            `json:"accepted"`
378			Disclaimer json.RawMessage `json:"disclaimer"`
379		}{true, eula.Disclaimer}
380		if err := pv.api.write(ctx, "accept the EULA", http.MethodPost, eulaPath, payload); err != nil {
381			return false, err
382		}
383		pv.say("the EULA was accepted because %s=yes", envAcceptEULA)
384		return true, nil
385	}
