387	// ---- blob store, realms, anonymous access -----------------------------------------------
388	
389	// requireBlobStore checks that the default blob store exists: the repositories
390	// are created on it.
391	func (pv *provisioner) requireBlobStore(ctx context.Context) error {
392		var stores []struct {
393			Name string `json:"name"`
394		}
395		if err := pv.api.read(ctx, "list the blob stores", blobStoresPath, nil, &stores); err != nil {
396			return err
397		}
398		for _, s := range stores {
399			if s.Name == defaultBlobStore {
400				return nil
401			}
402		}
403		return pv.fail("the blob store "+defaultBlobStore+" does not exist on the instance, so the repositories cannot be created",
404			"create a blob store named "+defaultBlobStore+" in the Nexus UI, or run `mise run nexus-bench:down` then `mise run nexus-bench:up`", nil)
405	}
