407	// ensureRealms adds the missing required realms to the active ones, keeping the
408	// others: replacing the list would drop a realm the instance needs.
409	func (pv *provisioner) ensureRealms(ctx context.Context) error {
410		var active []string
411		if err := pv.api.read(ctx, "read the active realms", activeRealms, nil, &active); err != nil {
412			return err
413		}
414		want := slices.Clone(active)
415		for _, realm := range requiredRealms {
416			if !slices.Contains(want, realm) {
417				want = append(want, realm)
418			}
419		}
420		if len(want) == len(active) {
421			pv.say("the realms are in place")
422			return nil
423		}
424		if err := pv.api.write(ctx, "set the active realms", http.MethodPut, activeRealms, want); err != nil {
425			return err
426		}
427		pv.say("the realms were set")
428		return nil
429	}
430	
431	// ensureAnonymous sets whether anonymous access is enabled, keeping the realm of
432	// the anonymous user as the instance has it.
433	func (pv *provisioner) ensureAnonymous(ctx context.Context) error {
434		var current struct {
435			RealmName string `json:"realmName"`
436		}
437		if err := pv.api.read(ctx, "read the anonymous access", anonymousPath, nil, &current); err != nil {
438			return err
439		}
440		if current.RealmName == "" {
441			current.RealmName = defaultAnonymousRealm
442		}
443		payload := map[string]any{"enabled": pv.p.Anonymous, "userId": anonymousUser, "realmName": current.RealmName}
444		if err := pv.api.write(ctx, "set the anonymous access", http.MethodPut, anonymousPath, payload); err != nil {
445			return err
446		}
447		pv.say("anonymous access enabled: %t", pv.p.Anonymous)
448		return nil
449	}
