526	// ---- repositories -----------------------------------------------------------------------
527	
528	type repositorySpec struct {
529		kind, name string
530		config     map[string]any
531	}
532	
533	// repositories returns the three Docker repositories, in the order they can be
534	// created: the group needs its members.
535	func (pv *provisioner) repositories() []repositorySpec {
536		storage := func(extra map[string]any) map[string]any {
537			s := map[string]any{"blobStoreName": defaultBlobStore, "strictContentTypeValidation": true}
538			for k, v := range extra {
539				s[k] = v
540			}
541			return s
542		}
543		// Anonymous pulls need the Docker API without a forced Basic auth.
544		docker := func(extra map[string]any) map[string]any {
545			d := map[string]any{"v1Enabled": false, "forceBasicAuth": false}
546			for k, v := range extra {
547				d[k] = v
548			}
549			return d
550		}
551		return []repositorySpec{
552			{"hosted", dockerHostedRepository, map[string]any{
553				"name": dockerHostedRepository, "online": true,
554				"storage": storage(map[string]any{"writePolicy": "ALLOW"}),
555				"docker":  docker(nil),
556			}},
557			{"proxy", dockerProxyRepository, map[string]any{
558				"name": dockerProxyRepository, "online": true,
559				"storage": storage(nil),
560				"docker":  docker(nil),
561				"proxy": map[string]any{
562					"remoteUrl": pv.p.UpstreamURL, "contentMaxAge": repositoryMaxAgeMinutes, "metadataMaxAge": repositoryMaxAgeMinutes,
563				},
564				"dockerProxy":   map[string]any{"indexType": "REGISTRY"},
565				"negativeCache": map[string]any{"enabled": true, "timeToLive": repositoryMaxAgeMinutes},
566				"httpClient":    map[string]any{"blocked": false, "autoBlock": true},
567			}},
568			{"group", dockerGroupRepository, map[string]any{
569				"name": dockerGroupRepository, "online": true,
570				"storage": storage(nil),
571				"docker":  docker(map[string]any{"httpPort": dockerContainerPort}),
572				"group":   map[string]any{"memberNames": []string{dockerHostedRepository, dockerProxyRepository}},
573			}},
574		}
575	}
576	
577	func (pv *provisioner) ensureRepositories(ctx context.Context) error {
578		for _, repo := range pv.repositories() {
579			collection := dockerReposPath + "/" + repo.kind
580			found, err := pv.api.get(ctx, fmt.Sprintf("read the %s repository %s", repo.kind, repo.name), collection+"/"+repo.name, nil, nil)
581			if err != nil {
582				return err
583			}
584			verb, method, path, done := "create", http.MethodPost, collection, "created"
585			if found {
586				verb, method, path, done = "update", http.MethodPut, collection+"/"+repo.name, "updated"
587			}
588			op := fmt.Sprintf("%s the %s repository %s", verb, repo.kind, repo.name)
589			if repo.name == dockerGroupRepository && pv.proxyPending {
