func TestRunPreflightRefusesInvalidParamsBeforeAnyCall(t *testing.T) {
	p := Defaults()
	p.Namespace = "default"
	f := newFakeKubectl(t, p)

	if _, err := RunPreflight(context.Background(), f, p, OpUp); err == nil {
